window.COPY = {"ca": {"skip": "Ves al contingut", "nav": ["L’experiència", "Les etapes", "El programa", "El guia", "Preparació", "Preu", "Preguntes", "Documents"], "menu": "Obre el menú", "close": "Tanca", "pdf": "Fitxa del viatge", "langLabel": "Idioma", "heroLabel": "BOLÍVIA · SERRALADA D’APOLOBAMBA", "heroTitle": "Apolobamba.<em>El camí ens uneix.</em>", "heroText": "Sis jornades a peu entre Pelechuco i Charazani, per camins de pastors i passos de més de 5.000 m. Grup reduït, guia de muntanya i guia local.", "heroCta": "Descobreix la travessa", "heroSecond": "Veure el programa dia a dia", "heroDate": "Juny de 2027 · millor època: de mitjan juny a finals de juliol", "photoNote": "Paisatge real d’Apolobamba", "facts": [["6", "jornades de marxa"], ["53 km", "de Pelechuco a Charazani"], ["5.032 m", "pas Sunchulli, el punt més alt"], ["11 + 2", "dies de programa i de reserva"]], "storyLabel": "01 / L’EXPERIÈNCIA", "storyTitle": "Caminar lluny.<br>Sentir-nos a prop.", "storyLead": "Hi ha viatges que es mesuren en quilòmetres. Aquest també es mesura en allò que aprenem pel camí.", "storyText": "De Pelechuco a Charazani, la travessa enllaça valls andines, passos alts i paisatges de pastura al peu de les glaceres de l’Apolobamba. És una ruta exigent i poc freqüentada, que recorrem sense presses, amb temps per al coneixement local i la convivència.", "storyCaption": "Des del camí a Charazani", "values": [["Territori viu", "Interpretem el paisatge amb respecte per les comunitats i el seu coneixement."], ["Un grup que camina junt", "Ritme compartit, reagrupaments i consignes clares."], ["Preparació amb criteri", "Guia de muntanya i guia local, amb un programa pensat per aclimatar-se bé."]], "routeLabel": "02 / LES ETAPES", "routeTitle": "Un camí.<br>Sis jornades per viure’l.", "routeIntro": "Cada dia caminem amb llum: sortida a partir de les 07.10 i arribada al campament abans de les 16.40, hora de Bolívia. Tria una jornada per veure’n les dades principals.", "stageLabel": "Jornada", "distance": "Distància", "ascent": "Ascens", "descent": "Descens", "duration": "Durada", "max": "Punt més alt", "stageFocus": "La clau de la jornada", "routeNote": "53,4 km en total. Distàncies i desnivells són aproximats i els horaris són de planificació: el recorregut encara s’ha de reconèixer sobre el terreny abans d’obrir reserves. Prop d’un terç del camí segueix pistes obertes per la mineria.", "stageNames": ["Pelechuco → Campament 1", "Campament 1 → Hilo Hilo", "Hilo Hilo → Campament 2", "Campament 2 → Incacancha", "Incacancha → Campament 3", "Campament 3 → Charazani"], "stageDescriptions": ["Sortim de Pelechuco per camins de pastors i pugem de manera sostinguda fins al primer pas, a 4.706 m. Baixem a la vall del riu Kotani i acampem al fons de la vall. Una jornada per trobar el ritme del grup i veure com respon cadascú a l’altitud.", "Jornada curta i suau fins a la comunitat d’Hilo Hilo. Dormim una mica més avall que la nit anterior i dediquem la tarda a descansar, hidratar-nos i preparar el pas alt de l’endemà.", "El dia gran de la travessa. Remuntem la vall fins al pas Sunchulli, a més de 5.000 m i amb les glaceres a prop, i baixem a acampar a la vall de Sunchulli, antiga zona minera.", "Tres passos enllaçats per damunt dels 4.500 m i el llarg descens en ziga-zaga de les Mil Corbes fins a Incacancha, on acampem vora les cascades.", "Curta en distància i intensa en desnivell. Pugem al pas d’Akamani, sota la muntanya sagrada dels kallawayes, passem l’apacheta de Tambillo i baixem al campament.", "Llarg descens cap a les valls habitades: cruïlla de Curva, pont sobre el riu, una última remuntada i arribada a Charazani."], "stageFocusText": ["Més de 1.000 m de pujada sostinguda i primera nit en tenda a 4.168 m.", "Dia de recuperació: caminar poc, beure molt i dormir bé.", "Hora límit per ser al coll: les 14.40. Amb neu dura o gel al pas, la jornada no es fa.", "El descens de les Mil Corbes demana atenció si el terreny és humit o gelat.", "La distància curta enganya: 600 m de pujada concentrada i fatiga acumulada.", "Si a la cruïlla de Curva anem justos de temps, acabem allà i fem l’últim tram en vehicle."], "journeyLabel": "03 / EL PROGRAMA", "journeyTitle": "Onze dies,<br>pas a pas.", "journeyIntro": "Tres dies a La Paz per aclimatar-nos, un de trasllat, sis jornades a peu i un de retorn.", "reserveTitle": "+ 2 dies de reserva", "reserveText": "Els fem servir si cal més aclimatació, si el temps obliga a esperar o si hi ha algun imprevist. Per això cal disposar de 13 dies, més els vols.", "methodLabel": "COM TREBALLEM", "methodTitle": "La preparació es nota<br>a cada pas.", "methodIntro": "La manera de guiar forma part de l’experiència. Preparar, observar, explicar i aprendre per millorar.", "methodSteps": [["Abans de caminar", "Conversa prèvia per valorar experiència i expectatives, reunió de grup i informació clara sobre nivell, material i possibles canvis."], ["Cada matí", "Briefing breu: objectiu del dia, condicions, aigua, punts de decisió i estat del grup."], ["Durant la jornada", "Ritme de grup, reagrupaments i explicacions sobre el paisatge i la cultura en llocs adequats. El dia del pas Sunchulli, la prioritat és caminar."], ["Després del viatge", "Revisió diària amb el grup, enquesta anònima i pla de millora per a la següent edició."]], "respectTitle": "El territori també ens acompanya.", "respectText": "Coneixement local, acords amb les comunitats, respecte pels camins i gestió responsable de residus i aigua. Les visites i les fotografies de persones es fan amb permís.", "prepLabel": "04 / PREPARACIÓ", "prepTitle": "Una bona motxilla.<br>Una bona preparació.", "prepIntro": "Per a persones amb experiència de travessa, capacitat per a jornades llargues i flexibilitat per conviure amb tendes, fred i canvis de programa.", "gearTitle": "La teva llista de material", "gearHint": "Marca el que ja tens preparat.", "gearCount": "elements preparats", "reset": "Desmarca-ho tot", "saved": "Les marques es desen només en aquest navegador. No s’envia cap dada.", "gearGroups": [["Roba i calçat", ["Botes de muntanya provades", "Mitjons adequats", "Capes tèrmiques i aïllament", "Jaqueta i pantalons impermeables", "Guants i gorro"]], ["Equip de travessa", ["Motxilla adequada", "Aigua, recipient i tractament acordat", "Frontal i energia de recanvi", "Sac i aïllant adequats al camp", "Bastons de trekking"]], ["Protecció i documents", ["Ulleres UV i protecció solar", "Alimentació i reserva acordades", "Documentació de viatge", "Medicació personal indicada", "Assegurança i contactes d’emergència"]]], "altitudeTitle": "L’altitud demana escoltar.", "altitudeText": "Estar en bona forma no garanteix adaptar-se bé. Passem cinc nits per sobre dels 4.000 m i creuem un coll a més de 5.000 m. Abans del viatge cal una revisió amb medicina del viatge.", "altitudePoints": ["Avisa el guia de qualsevol malestar.", "Amb símptomes no es puja a dormir més amunt.", "Si el grup ho necessita, s’allarga o es modifica el programa."], "priceLabel": "05 / PREU DE REFERÈNCIA", "priceTitle": "Saber què hi ha<br>darrere del viatge.", "priceNote": "Preu de referència per a un grup mínim de 6 persones i un màxim de 12. És una estimació del projecte, pendent dels pressupostos reals dels proveïdors locals.", "perPerson": "per persona", "included": "Què inclou", "includeItems": ["Guia de muntanya i guia local", "Trasllats La Paz–Pelechuco i Charazani–La Paz", "Mules i suport de càrregues", "Àpats i allotjament de tot el programa", "Tendes i material col·lectiu", "Assegurança de viatge i activitat"], "excluded": "Què no inclou", "excludeItems": ["Vols internacionals", "Equip personal: sac, aïllant, roba i botes", "Despeses personals i propines"], "priceDisclaimer": "Les reserves encara no estan obertes. Dates, preu i serveis es confirmaran després del reconeixement del recorregut.", "priceCta": "Veure les condicions", "docsLabel": "07 / DOCUMENTACIÓ", "docsTitle": "Tot el que necessites<br>per preparar el viatge.", "docsIntro": "Documents per llegir amb calma, imprimir o portar al mòbil. El dossier complet te l’enviem personalment.", "docs": [["Fitxa del viatge", "1 pàgina · PDF", "Programa dia a dia, dades de cada jornada, preu i què inclou."], ["Preparació i material", "2 pàgines · PDF", "Salut i altitud, documents, què porten les mules i llista de material per marcar."], ["Pla d’entrenament", "12 setmanes · PDF", "Què fer cada setmana per arribar preparat, amb treball de força i proves de material."], ["Dossier complet del viatge", "PDF · per WhatsApp", "Etapes punt a punt amb mapes i horaris, clima de juny, allotjaments, preparació i condicions. Te l’enviem quan ens escrius."]], "download": "Descarrega", "sourcesLabel": "Fonts amb què hem contrastat la ruta", "sourcesText": "El traçat prové d’un registre GPS de 2012. L’hem comparat amb programes d’operadors bolivians que fan la mateixa travessa i amb relats de 2022–2025. Cap d’aquestes fonts substitueix el reconeixement sobre el terreny.", "sourcesButton": "Consulta les fonts", "sources": [["Track GPS · Gallotrekk (Wikiloc)", "Registre real del recorregut de 2012: traçat, waypoints i temps de cada etapa."], ["Operador · Bolivian Mountain Guides", "Programa Pelechuco–Charazani: campaments a Palca, Sunchulli i Jatunpampa; pas Sunchulli a 5.100 m."], ["Operador · Kaleidoscope Travel", "Camp vora el riu Illo Illo i unes 6 h fins a Sunchulli; final a Curva."], ["Operador · ZigZag Bolivia", "Unes 9 h de Palca a Sunchulli sense nit intermèdia; camp a 4.500 m."], ["2022 · Expedició Colli", "Entrevista a participants d’una travessa de cinc dies pel mateix corredor."], ["2022 · Registre de caminant", "Track publicat a Wikiloc; no acredita el tram final fins a Charazani."], ["2024 · Relat audiovisual", "Vídeo de la travessa Pelechuco–Charazani, publicat l’octubre de 2024."], ["2025 · Accés a Pelechuco", "Relat del viatge en 4×4 fins a Pelechuco."]], "faqLabel": "06 / ABANS DE DECIDIR", "faqTitle": "Preguntes del camí.", "faqs": [["És adequada com a primera travessa?", "No. Està pensada per a senderistes amb experiència en travesses de diversos dies, acostumats a jornades llargues i a dormir en tenda. Abans de reservar fem una conversa per valorar preparació i expectatives."], ["Quants dies necessito?", "El programa dura 11 dies: tres d’aclimatació a La Paz, un de trasllat, sis jornades a peu i un de retorn. Hi afegim dos dies de reserva, de manera que cal disposar de 13 dies, més els vols."], ["Quina és la jornada més exigent?", "La del pas Sunchulli, el dia 7: 11,4 km, uns 1.060 m de pujada, entre 7 i 9 hores i un coll a més de 5.000 m. Per això el dia abans és curt i dormim a Hilo Hilo."], ["On es dorm?", "Hotel a La Paz, allotjament local senzill a Pelechuco i Charazani i cinc nits en tenda, entre 4.000 i 4.700 m. Les nits són fredes, sovint sota zero."], ["Quina és la millor època?", "De mitjan juny a finals de juliol, el cor de l’estació seca. Maig i setembre són possibles però més incerts, i a l’agost hi ha hagut nevades fortes al pas Sunchulli. Proposem la segona quinzena de juny de 2027."], ["He de carregar tot l’equipatge?", "No. El programa preveu mules per a tendes, cuina i equipatge; durant el dia portes una motxilla amb roba d’abric, aigua i menjar."], ["L’aigua és potable?", "No es beu directament. A la zona hi ha mineria d’or, i tractar l’aigua no n’elimina els metalls: l’agafem només de fonts per sobre de les mines o que la comunitat ens confirma, la tractem sempre i en portem de reserva al tram de Sunchulli."], ["Què passa si fa mal temps o algú no es troba bé?", "El guia pot aturar, escurçar o modificar una jornada, i cada jornada té un pla B preparat. Tenim dos dies de reserva, una ruta alternativa completa (el pla C, per Cañisaya i l’Akamani) i, a gairebé tot el recorregut, sortida en vehicle si cal. Amb neu dura o gel als passos, no es creua."], ["Necessito assegurança?", "El preu inclou una assegurança de viatge i activitat que cobreix trekking fins a 5.100 m, rescat i repatriació. Si ja en tens una, revisa-ho amb nosaltres per no duplicar cobertures."], ["El recorregut està revisat sobre el terreny?", "Encara no. El programa està planificat sobre un track GPS de 2012 i contrastat amb els itineraris que publiquen operadors bolivians. Abans d’obrir reserves cal un reconeixement de passos, campaments, aigua i el pont de l’última jornada."], ["Ja es pot reservar?", "Encara no. Aquesta web presenta un projecte acadèmic de tècnic esportiu (TD2). Juny de 2027 és una proposta de dates; les reserves s’obririen després de validar el recorregut, els serveis, els permisos i les assegurances."]], "endLabel": "EL PRIMER PAS", "endTitle": "Coneix el viatge.<br>Prepara el teu camí.", "endText": "Mira el programa complet i comprova si la proposta encaixa amb la teva experiència.", "footerLine": "Muntanya, territori i camí compartit.", "footerNote": "Projecte acadèmic TD2 · Izan Pimentel Pérez", "privacy": "Privacitat", "terms": "Condicions del projecte", "credits": "Fotografia i cartografia", "privacyText": "Aquesta web no recull reserves ni dades personals. La llengua i les marques de la llista de material es desen només al teu navegador i les pots esborrar amb els controls de la pàgina. Els enllaços externs tenen les seves pròpies condicions.", "termsText": "Andes Wild Trek és un projecte acadèmic de tècnic esportiu (TD2). Dates, preu i serveis són orientatius i no constitueixen una oferta vinculant. Abans d’obrir reserves s’han de validar el recorregut, els proveïdors, els permisos, les assegurances i les condicions de contractació.", "creditIntro": "Fotografies documentals d’Apolobamba i Pelechuco, amb autoria i llicència identificades. La seva data no certifica l’estat actual del recorregut.", "mapNotice": "Els mapes utilitzen dades OpenStreetMap i SRTM i l’estil OpenTopoMap, CC-BY-SA. El traçat és un registre GPS de 2012.", "dismiss": "Tanca la finestra", "notice": "", "dayWord": "Dia", "night": "On dormim", "schedule": "Horari previst", "scheduleText": "Sortida {0} · arribada {1}", "approx": "aprox.", "stageTabs": ["Campament 1", "Hilo Hilo", "Pas Sunchulli", "Incacancha", "Akamani", "Charazani"], "itinCols": ["Dia", "Jornada", "Què fem", "Nit"], "itinerary": [["1", "Arribada a La Paz", "Trasllat a l’hotel, descans i primera trobada del grup.", "Hotel · 3.650 m"], ["2", "Adaptació a La Paz", "Passeig suau per la ciutat, hidratació i descans.", "Hotel · 3.650 m"], ["3", "Aclimatació i preparació", "Caminada moderada, revisió de material i reunió prèvia.", "Hotel · 3.650 m"], ["4", "La Paz → Pelechuco", "Trasllat en 4×4 pel llac Titicaca i l’altiplà d’Ulla Ulla. Unes 12 hores.", "Allotjament local · 3.660 m"], ["5", "Pelechuco → Campament 1", "9,7 km · +1.047 m · 6–8 h", "Tenda · 4.168 m"], ["6", "Campament 1 → Hilo Hilo", "4,2 km · 2–3 h · tarda de descans", "Tenda · 4.010 m"], ["7", "Hilo Hilo → pas Sunchulli → Campament 2", "11,4 km · +1.062 m · 7–9 h", "Tenda · 4.500–4.700 m"], ["8", "Campament 2 → Incacancha", "8,3 km · −867 m · 5–7 h", "Tenda · 4.060 m"], ["9", "Incacancha → Campament 3", "4,1 km · +602 m · 4–6 h", "Tenda · 4.171 m"], ["10", "Campament 3 → Charazani", "15,8 km · −1.473 m · 8–9 h 30 min", "Allotjament local · 3.195 m"], ["11", "Charazani → La Paz", "Retorn en vehicle (7–8 hores) i comiat.", "Fi del viatge"]], "priceAmount": "3.800", "hubLabel": "EL TREBALL BLOC A BLOC", "hubTitle": "El projecte,<br>bloc a bloc.", "hubIntro": "Els sis blocs del treball, en PDF. Pots obrir-los, descarregar-los o cercar dins del seu contingut.", "hubFull": "Treball complet", "hubChanges": "Canvis i decisions pendents", "hubSearch": "Cerca dins del treball", "hubSearchPh": "Pressupost, permisos, checklist, Sunchulli…", "hubPresent": "Mode exposició", "hubPresentOff": "Surt del mode exposició", "hubCount": "{0} de 6 blocs", "hubPages": "pàgines", "hubMeta": "PDF · català", "hubOpen": "Obre el PDF", "hubDownload": "Descarrega", "hubRead": "Llegeix el text aquí", "hubNav": "Blocs del treball", "igLabel": "INSTAGRAM / MAQUETA ACADÈMICA", "igText": "Sis publicacions de mostra de la campanya de vuit setmanes. És una maqueta del pla de màrqueting; no és un compte real.", "igCta": "Consulta el pla de màrqueting", "igPosts": ["Sis jornades, un sol camí. Presentem la travessa.", "5.032 m: el dia del pas Sunchulli.", "Pelechuco, on comença tot.", "Què porto a la motxilla? La llista, a la web.", "Grup petit: de 6 a 12 persones.", "Tres dies a La Paz abans de caminar."], "igCredit": "Fotografies: Realnif, Raullike i Das Morton · Wikimedia Commons · CC BY-SA 4.0.", "treballNav": "Treball TD2", "condLabel": "CONDICIONS DEL VIATGE", "condTitle": "Les condicions, clares des del principi.", "conds": [["Grup mínim i màxim", "El viatge surt amb un mínim de 6 persones i un màxim de 12. Si no s’arriba al mínim, t’avisem amb temps i et proposem una altra data o et retornem tot el que hagis pagat."], ["Què inclou el preu", "Guia de muntanya i guia local (amb 9–12 persones s’hi afegeix suport local), trasllats en 4×4 del programa, mules, tots els àpats i allotjaments del programa, tendes i material col·lectiu, i assegurança de viatge i activitat amb trekking fins a 5.100 m, rescat i repatriació."], ["Dies de reserva", "Els dos dies de reserva estan inclosos en el preu. Si s’han d’utilitzar, no tenen cost addicional. Si una situació exigís més dies, t’informaríem del nou programa i del cost abans de continuar."], ["Requisits per participar", "Experiència en travesses de diversos dies, conversa prèvia amb el guia, revisió amb medicina del viatge i passaport vigent. Cal disposar de 13 dies, més els vols."], ["Com es reserva", "Quan s’obrin les reserves: conversa prèvia, confirmació de plaça i contracte de viatge combinat amb el calendari de pagaments i les condicions de cancel·lació. Andes Wild Trek actua com a organitzador del viatge."], ["Canvis durant el viatge", "El guia pot modificar, escurçar o aturar una jornada per seguretat, meteorologia o estat del grup. L’última jornada es pot acabar a Curva amb vehicle. Aquests canvis no tenen cost addicional."]], "condNote": "Les reserves encara no estan obertes. Dates, preu i condicions definitives es confirmaran després del reconeixement del recorregut.", "tw": {"title": "Treball TD2 · Andes Wild Trek · Apolobamba", "nav": ["El viatge", "El treball", "Plans B i C", "Blocs", "Eines", "Fonts"], "eyebrow": "TREBALL ACADÈMIC · TÈCNIC ESPORTIU EN MITJA MUNTANYA", "h1": "Andes Wild Trek<br>Apolobamba", "lead": "Projecte de creació d’una empresa de guiatge i d’una travessa de sis jornades entre Pelechuco i Charazani, Bolívia.", "meta": "Izan Pimentel Pérez · 16 de novembre de 2026", "full": "Treball complet (PDF)", "word": "Versió editable (Word)", "back": "Veure la web del viatge", "keyLabel": "EL PROJECTE EN QUATRE PUNTS", "keys": [["Empresa", "Agència organitzadora de viatges combinats amb base a Catalunya i operador local a Bolívia."], ["Programa", "11 dies i 2 de reserva: 3 d’aclimatació, 1 de trasllat, 6 jornades a peu i 1 de retorn. Millor època: de mitjan juny a finals de juliol."], ["Pressupost", "3.800 € per persona amb un mínim de 6; marge objectiu del 30%."], ["Següent pas", "Reconeixement de camp, cotitzacions locals i permisos abans de comercialitzar."]], "present": "Presentació", "presentOff": "Surt del mode exposició", "toolsLabel": "EINES DEL GUIA I ANNEXOS", "toolsTitle": "Per aplicar-lo<br>sobre el terreny.", "tools": [["Formularis operatius", "10 pàgines · PDF", "Checklist diari, enquesta, autoavaluació, informe de millora i expedient d’obertura.", "dossiers/Apolobamba_Formularis_Operatius.pdf"], ["Atles cartogràfic", "10 làmines · PDF A3", "Les sis jornades a peu i les quatre etapes del pla C, amb mapa topogràfic, perfil, punts de pas i vies d’evacuació.", "dossiers/Apolobamba_Atles_Cartografic_A3.pdf"], ["Flyer amb QR", "Imatge · JPG", "Peça del pla de màrqueting amb fotografia real; el QR obre la web del viatge.", "assets/flyer.jpg"], ["App del guia", "Mòbil · sense cobertura", "Fitxes tècniques de cada jornada amb hores de control i decisions, meteo, seguretat, llistes, GPX i «On soc?».", "guia/"], ["Dossier complet del client", "18 pàgines · PDF", "Document que s’envia al client quan contacta: etapes punt a punt, mapes, clima i condicions.", "dossiers/client/Dossier_Viatge_CA.pdf"]], "open": "Obre", "sourcesLabel": "FONTS", "sourcesTitle": "Contrast de la ruta", "mapLabel": "MAPA DEL TREBALL", "mapTitle": "Com encaixen les peces.", "map": [["Empresa i mercat", [["Entorn laboral", "Model d’agència, públic i DAFO", "empresa"], ["Normativa", "Titulació, contracte i assegurances", "normativa"], ["Màrqueting", "Missatge, campanya i flyer", "marketing"]]], ["Producte", [["Programa", "11 dies + 2, sis jornades i aclimatació", "empresa"], ["Pressupost", "3.800 € amb un mínim de 6", "empresa"], ["Fitxa del client", "Què rep qui s’hi apunta", "client"]]], ["Operació", [["Metodologia", "Conducció, dinàmiques i avaluació", "metodologia"], ["Fitxa del guia", "Horaris, punts de decisió i mapes", "guia"], ["Formularis", "Checklist, enquesta i expedient", "eines"]]]], "mapBase": "Tot el treball descansa en dos límits: les competències del TD2 al pas Sunchulli i el reconeixement de camp previ a la venda.", "planLabel": "TEMPORADA, PLANS B I PLA C", "planHeading": "Quan anar-hi<br>i què fem si no es pot passar.", "planIntro": "Revisió del 17/11/2026 amb fonts de muntanyencs, operadors, l’ABC i OpenStreetMap. Cada jornada té plans B i vies d’evacuació, i el pla C és una ruta completa per l’Akamani.", "planBTitle": "Plans B per jornada", "planCTitle": "Fitxes tècniques del pla C", "roadsNote": "Consultat el", "colsC": ["Etapa", "Dia", "Km", "Desnivell", "Màx.", "Durada", "Horari", "Nit"]}, "stageDossier": "Els punts de pas, els mapes i els horaris detallats de cada jornada són al dossier complet, que t’enviem quan ens escrius.", "docRequest": "Demana’l", "seasonLabel": "QUAN ANAR-HI", "planTitle": "Si el camí no deixa passar", "planText": "Cada jornada té un pla B preparat i hi ha una ruta alternativa completa. Si cal canviar, el guia ho decideix pensant en la seguretat del grup.", "planItems": [["Pas Sunchulli (5.032 m)", "Hi ha hora límit: les 14.40. Si no hi arribem a temps, si hi ha neu dura o gel o si el temps és dolent, tornem a Hilo Hilo i fem servir un dia de reserva."], ["Baixada de les Mil Corbes", "Amb neu, gel o poca visibilitat no hi entrem. Hi ha una baixada alternativa més llarga i menys dreta, o podem dormir a la comunitat de Quellwa Cota."], ["Final de la travessa", "Si anem justos de temps, acabem a Curva i seguim en vehicle fins a Charazani."], ["Pla C · per l’Akamani", "Si el pas Sunchulli no és practicable o la zona minera no ho aconsella, fem la travessa per Cañisaya i el camí de l’Akamani fins a Charazani: quatre jornades, 35 km i un màxim de 4.661 m."], ["Pistes i evacuació", "Prop d’un terç del camí va per pistes mineres. A canvi, a gairebé tot el recorregut un vehicle pot arribar si cal evacuar algú."]]}, "es": {"skip": "Ir al contenido", "nav": ["La experiencia", "Las etapas", "El programa", "El guía", "Preparación", "Precio", "Preguntas", "Documentos"], "menu": "Abrir menú", "close": "Cerrar", "pdf": "Ficha del viaje", "langLabel": "Idioma", "heroLabel": "BOLIVIA · CORDILLERA DE APOLOBAMBA", "heroTitle": "Apolobamba.<em>El camino nos une.</em>", "heroText": "Seis jornadas a pie entre Pelechuco y Charazani, por caminos de pastores y pasos de más de 5.000 m. Grupo reducido, guía de montaña y guía local.", "heroCta": "Descubre la travesía", "heroSecond": "Ver el programa día a día", "heroDate": "Junio de 2027 · mejor época: de mediados de junio a finales de julio", "photoNote": "Paisaje real de Apolobamba", "facts": [["6", "jornadas de marcha"], ["53 km", "de Pelechuco a Charazani"], ["5.032 m", "paso Sunchulli, el punto más alto"], ["11 + 2", "días de programa y de reserva"]], "storyLabel": "01 / LA EXPERIENCIA", "storyTitle": "Caminar lejos.<br>Sentirnos cerca.", "storyLead": "Hay viajes que se miden en kilómetros. Este también se mide en lo que aprendemos por el camino.", "storyText": "De Pelechuco a Charazani, la travesía enlaza valles andinos, pasos altos y paisajes de pastoreo al pie de los glaciares de Apolobamba. Es una ruta exigente y poco frecuentada, que recorremos sin prisas, con tiempo para el conocimiento local y la convivencia.", "storyCaption": "Desde el camino a Charazani", "values": [["Territorio vivo", "Interpretamos el paisaje con respeto por las comunidades y su conocimiento."], ["Un grupo que camina junto", "Ritmo compartido, reagrupamientos e instrucciones claras."], ["Preparación con criterio", "Guía de montaña y guía local, con un programa pensado para aclimatarse bien."]], "routeLabel": "02 / LAS ETAPAS", "routeTitle": "Un camino.<br>Seis jornadas para vivirlo.", "routeIntro": "Cada día caminamos con luz: salida a partir de las 07:10 y llegada al campamento antes de las 16:40, hora de Bolivia. Elige una jornada para ver sus datos principales.", "stageLabel": "Jornada", "distance": "Distancia", "ascent": "Ascenso", "descent": "Descenso", "duration": "Duración", "max": "Punto más alto", "stageFocus": "La clave de la jornada", "routeNote": "53,4 km en total. Distancias y desniveles son aproximados y los horarios son de planificación: el recorrido todavía debe reconocerse sobre el terreno antes de abrir reservas. Cerca de un tercio del camino sigue pistas abiertas por la minería.", "stageNames": ["Pelechuco → Campamento 1", "Campamento 1 → Hilo Hilo", "Hilo Hilo → Campamento 2", "Campamento 2 → Incacancha", "Incacancha → Campamento 3", "Campamento 3 → Charazani"], "stageDescriptions": ["Salimos de Pelechuco por caminos de pastores y subimos de forma sostenida hasta el primer paso, a 4.706 m. Bajamos al valle del río Kotani y acampamos en el fondo del valle. Una jornada para encontrar el ritmo del grupo y ver cómo responde cada persona a la altitud.", "Jornada corta y suave hasta la comunidad de Hilo Hilo. Dormimos algo más abajo que la noche anterior y dedicamos la tarde a descansar, hidratarnos y preparar el paso alto del día siguiente.", "El gran día de la travesía. Remontamos el valle hasta el paso Sunchulli, a más de 5.000 m y con los glaciares cerca, y bajamos a acampar al valle de Sunchulli, antigua zona minera.", "Tres pasos enlazados por encima de los 4.500 m y el largo descenso en zigzag de las Mil Curvas hasta Incacancha, donde acampamos junto a las cascadas.", "Corta en distancia e intensa en desnivel. Subimos al paso de Akamani, bajo la montaña sagrada de los kallawayas, pasamos la apacheta de Tambillo y bajamos al campamento.", "Largo descenso hacia los valles habitados: cruce de Curva, puente sobre el río, una última remontada y llegada a Charazani."], "stageFocusText": ["Más de 1.000 m de subida sostenida y primera noche en tienda a 4.168 m.", "Día de recuperación: caminar poco, beber mucho y dormir bien.", "Hora límite para estar en el collado: las 14:40. Con nieve dura o hielo en el paso, la jornada no se hace.", "El descenso de las Mil Curvas pide atención si el terreno está húmedo o helado.", "La distancia corta engaña: 600 m de subida concentrada y fatiga acumulada.", "Si en el cruce de Curva vamos justos de tiempo, terminamos allí y hacemos el último tramo en vehículo."], "journeyLabel": "03 / EL PROGRAMA", "journeyTitle": "Once días,<br>paso a paso.", "journeyIntro": "Tres días en La Paz para aclimatarnos, uno de traslado, seis jornadas a pie y uno de regreso.", "reserveTitle": "+ 2 días de reserva", "reserveText": "Los usamos si hace falta más aclimatación, si el tiempo obliga a esperar o si surge algún imprevisto. Por eso hay que disponer de 13 días, más los vuelos.", "methodLabel": "CÓMO TRABAJAMOS", "methodTitle": "La preparación se nota<br>en cada paso.", "methodIntro": "La forma de guiar forma parte de la experiencia. Preparar, observar, explicar y aprender para mejorar.", "methodSteps": [["Antes de caminar", "Conversación previa para valorar experiencia y expectativas, reunión de grupo e información clara sobre nivel, material y posibles cambios."], ["Cada mañana", "Briefing breve: objetivo del día, condiciones, agua, puntos de decisión y estado del grupo."], ["Durante la jornada", "Ritmo de grupo, reagrupamientos y explicaciones sobre el paisaje y la cultura en lugares adecuados. El día del paso Sunchulli, la prioridad es caminar."], ["Después del viaje", "Revisión diaria con el grupo, encuesta anónima y plan de mejora para la siguiente edición."]], "respectTitle": "El territorio también nos acompaña.", "respectText": "Conocimiento local, acuerdos con las comunidades, respeto por los caminos y gestión responsable de residuos y agua. Las visitas y fotografías de personas se hacen con permiso.", "prepLabel": "04 / PREPARACIÓN", "prepTitle": "Una buena mochila.<br>Una buena preparación.", "prepIntro": "Para personas con experiencia de travesía, capacidad para jornadas largas y flexibilidad para convivir con tiendas, frío y cambios de programa.", "gearTitle": "Tu lista de material", "gearHint": "Marca lo que ya tienes preparado.", "gearCount": "elementos preparados", "reset": "Desmarcar todo", "saved": "Las marcas se guardan solo en este navegador. No se envía ningún dato.", "gearGroups": [["Ropa y calzado", ["Botas de montaña probadas", "Calcetines adecuados", "Capas térmicas y aislamiento", "Chaqueta y pantalón impermeables", "Guantes y gorro"]], ["Equipo de travesía", ["Mochila adecuada", "Agua, recipiente y tratamiento acordado", "Frontal y energía de repuesto", "Saco y aislante adecuados al campamento", "Bastones de trekking"]], ["Protección y documentos", ["Gafas UV y protección solar", "Alimentación y reserva acordadas", "Documentación de viaje", "Medicación personal indicada", "Seguro y contactos de emergencia"]]], "altitudeTitle": "La altitud pide escuchar.", "altitudeText": "Estar en buena forma no garantiza adaptarse bien. Pasamos cinco noches por encima de los 4.000 m y cruzamos un collado a más de 5.000 m. Antes del viaje hace falta una revisión con medicina del viajero.", "altitudePoints": ["Avisa al guía de cualquier malestar.", "Con síntomas no se sube a dormir más alto.", "Si el grupo lo necesita, se amplía o modifica el programa."], "priceLabel": "05 / PRECIO DE REFERENCIA", "priceTitle": "Saber qué hay<br>detrás del viaje.", "priceNote": "Precio de referencia para un grupo mínimo de 6 personas y un máximo de 12. Es una estimación del proyecto, pendiente de los presupuestos reales de los proveedores locales.", "perPerson": "por persona", "included": "Qué incluye", "includeItems": ["Guía de montaña y guía local", "Traslados La Paz–Pelechuco y Charazani–La Paz", "Mulas y apoyo de cargas", "Comidas y alojamiento de todo el programa", "Tiendas y material colectivo", "Seguro de viaje y actividad"], "excluded": "Qué no incluye", "excludeItems": ["Vuelos internacionales", "Equipo personal: saco, aislante, ropa y botas", "Gastos personales y propinas"], "priceDisclaimer": "Las reservas todavía no están abiertas. Fechas, precio y servicios se confirmarán tras el reconocimiento del recorrido.", "priceCta": "Ver las condiciones", "docsLabel": "07 / DOCUMENTACIÓN", "docsTitle": "Todo lo que necesitas<br>para preparar el viaje.", "docsIntro": "Documentos para leer con calma, imprimir o llevar en el móvil. El dossier completo te lo enviamos personalmente.", "docs": [["Ficha del viaje", "1 página · PDF", "Programa día a día, datos de cada jornada, precio y qué incluye."], ["Preparación y material", "2 páginas · PDF", "Salud y altitud, documentos, qué llevan las mulas y lista de material para marcar."], ["Plan de entrenamiento", "12 semanas · PDF", "Qué hacer cada semana para llegar preparado, con trabajo de fuerza y pruebas de material."], ["Dossier completo del viaje", "PDF · por WhatsApp", "Etapas punto a punto con mapas y horarios, clima de junio, alojamientos, preparación y condiciones. Te lo enviamos cuando nos escribes."]], "download": "Descargar", "sourcesLabel": "Fuentes con las que hemos contrastado la ruta", "sourcesText": "El trazado procede de un registro GPS de 2012. Lo hemos comparado con programas de operadores bolivianos que hacen la misma travesía y con relatos de 2022–2025. Ninguna de estas fuentes sustituye el reconocimiento sobre el terreno.", "sourcesButton": "Consulta las fuentes", "sources": [["Track GPS · Gallotrekk (Wikiloc)", "Registro real del recorrido de 2012: trazado, waypoints y tiempos de cada etapa."], ["Operador · Bolivian Mountain Guides", "Programa Pelechuco–Charazani: campamentos en Palca, Sunchulli y Jatunpampa; paso Sunchulli a 5.100 m."], ["Operador · Kaleidoscope Travel", "Campamento junto al río Illo Illo y unas 6 h hasta Sunchulli; final en Curva."], ["Operador · ZigZag Bolivia", "Unas 9 h de Palca a Sunchulli sin noche intermedia; campamento a 4.500 m."], ["2022 · Expedición Colli", "Entrevista a participantes de una travesía de cinco días por el mismo corredor."], ["2022 · Registro de caminante", "Track publicado en Wikiloc; no acredita el tramo final hasta Charazani."], ["2024 · Relato audiovisual", "Vídeo de la travesía Pelechuco–Charazani, publicado en octubre de 2024."], ["2025 · Acceso a Pelechuco", "Relato del viaje en 4×4 hasta Pelechuco."]], "faqLabel": "06 / ANTES DE DECIDIR", "faqTitle": "Preguntas del camino.", "faqs": [["¿Es adecuada como primera travesía?", "No. Está pensada para senderistas con experiencia en travesías de varios días, acostumbrados a jornadas largas y a dormir en tienda. Antes de reservar hacemos una conversación para valorar preparación y expectativas."], ["¿Cuántos días necesito?", "El programa dura 11 días: tres de aclimatación en La Paz, uno de traslado, seis jornadas a pie y uno de regreso. Añadimos dos días de reserva, así que hay que disponer de 13 días, más los vuelos."], ["¿Cuál es la jornada más exigente?", "La del paso Sunchulli, el día 7: 11,4 km, unos 1.060 m de subida, entre 7 y 9 horas y un collado a más de 5.000 m. Por eso el día anterior es corto y dormimos en Hilo Hilo."], ["¿Dónde se duerme?", "Hotel en La Paz, alojamiento local sencillo en Pelechuco y Charazani y cinco noches en tienda, entre 4.000 y 4.700 m. Las noches son frías, a menudo bajo cero."], ["¿Cuál es la mejor época?", "De mediados de junio a finales de julio, el corazón de la estación seca. Mayo y septiembre son posibles pero más inciertos, y en agosto ha habido nevadas fuertes en el paso Sunchulli. Proponemos la segunda quincena de junio de 2027."], ["¿Tengo que cargar todo el equipaje?", "No. El programa prevé mulas para tiendas, cocina y equipaje; durante el día llevas una mochila con ropa de abrigo, agua y comida."], ["¿El agua es potable?", "No se bebe directamente. En la zona hay minería de oro, y tratar el agua no elimina los metales: la cogemos solo de fuentes por encima de las minas o que la comunidad nos confirma, la tratamos siempre y llevamos de reserva en el tramo de Sunchulli."], ["¿Qué pasa si hace mal tiempo o alguien no se encuentra bien?", "El guía puede detener, acortar o modificar una jornada, y cada jornada tiene un plan B preparado. Tenemos dos días de reserva, una ruta alternativa completa (el plan C, por Cañisaya y el Akamani) y, en casi todo el recorrido, salida en vehículo si hace falta. Con nieve dura o hielo en los pasos, no se cruza."], ["¿Necesito seguro?", "El precio incluye un seguro de viaje y actividad que cubre trekking hasta 5.100 m, rescate y repatriación. Si ya tienes uno, revísalo con nosotros para no duplicar coberturas."], ["¿El recorrido está revisado sobre el terreno?", "Todavía no. El programa está planificado sobre un track GPS de 2012 y contrastado con los itinerarios que publican operadores bolivianos. Antes de abrir reservas hace falta un reconocimiento de pasos, campamentos, agua y el puente de la última jornada."], ["¿Ya se puede reservar?", "Todavía no. Esta web presenta un proyecto académico de técnico deportivo (TD2). Junio de 2027 es una propuesta de fechas; las reservas se abrirían después de validar el recorrido, los servicios, los permisos y los seguros."]], "endLabel": "EL PRIMER PASO", "endTitle": "Conoce el viaje.<br>Prepara tu camino.", "endText": "Mira el programa completo y comprueba si la propuesta encaja con tu experiencia.", "footerLine": "Montaña, territorio y camino compartido.", "footerNote": "Proyecto académico TD2 · Izan Pimentel Pérez", "privacy": "Privacidad", "terms": "Condiciones del proyecto", "credits": "Fotografía y cartografía", "privacyText": "Esta web no recoge reservas ni datos personales. El idioma y las marcas de la lista de material se guardan solo en tu navegador y puedes borrarlas con los controles de la página. Los enlaces externos tienen sus propias condiciones.", "termsText": "Andes Wild Trek es un proyecto académico de técnico deportivo (TD2). Fechas, precio y servicios son orientativos y no constituyen una oferta vinculante. Antes de abrir reservas deben validarse el recorrido, los proveedores, los permisos, los seguros y las condiciones de contratación.", "creditIntro": "Fotografías documentales de Apolobamba y Pelechuco, con autoría y licencia identificadas. Su fecha no certifica el estado actual del recorrido.", "mapNotice": "Los mapas utilizan datos OpenStreetMap y SRTM y el estilo OpenTopoMap, CC-BY-SA. El trazado es un registro GPS de 2012.", "dismiss": "Cerrar la ventana", "notice": "", "dayWord": "Día", "night": "Dónde dormimos", "schedule": "Horario previsto", "scheduleText": "Salida {0} · llegada {1}", "approx": "aprox.", "stageTabs": ["Campamento 1", "Hilo Hilo", "Paso Sunchulli", "Incacancha", "Akamani", "Charazani"], "itinCols": ["Día", "Jornada", "Qué hacemos", "Noche"], "itinerary": [["1", "Llegada a La Paz", "Traslado al hotel, descanso y primer encuentro del grupo.", "Hotel · 3.650 m"], ["2", "Adaptación en La Paz", "Paseo suave por la ciudad, hidratación y descanso.", "Hotel · 3.650 m"], ["3", "Aclimatación y preparación", "Caminata moderada, revisión de material y reunión previa.", "Hotel · 3.650 m"], ["4", "La Paz → Pelechuco", "Traslado en 4×4 por el lago Titicaca y el altiplano de Ulla Ulla. Unas 12 horas.", "Alojamiento local · 3.660 m"], ["5", "Pelechuco → Campamento 1", "9,7 km · +1.047 m · 6–8 h", "Tienda · 4.168 m"], ["6", "Campamento 1 → Hilo Hilo", "4,2 km · 2–3 h · tarde de descanso", "Tienda · 4.010 m"], ["7", "Hilo Hilo → paso Sunchulli → Campamento 2", "11,4 km · +1.062 m · 7–9 h", "Tienda · 4.500–4.700 m"], ["8", "Campamento 2 → Incacancha", "8,3 km · −867 m · 5–7 h", "Tienda · 4.060 m"], ["9", "Incacancha → Campamento 3", "4,1 km · +602 m · 4–6 h", "Tienda · 4.171 m"], ["10", "Campamento 3 → Charazani", "15,8 km · −1.473 m · 8–9 h 30 min", "Alojamiento local · 3.195 m"], ["11", "Charazani → La Paz", "Regreso en vehículo (7–8 horas) y despedida.", "Fin del viaje"]], "priceAmount": "3.800", "hubLabel": "EL TRABAJO BLOQUE A BLOQUE", "hubTitle": "El proyecto,<br>bloque a bloque.", "hubIntro": "Los seis bloques del trabajo, en PDF y en catalán. Puedes abrirlos, descargarlos o buscar dentro de su contenido.", "hubFull": "Trabajo completo", "hubChanges": "Cambios y decisiones pendientes", "hubSearch": "Busca dentro del trabajo", "hubSearchPh": "Presupuesto, permisos, checklist, Sunchulli…", "hubPresent": "Modo exposición", "hubPresentOff": "Salir del modo exposición", "hubCount": "{0} de 6 bloques", "hubPages": "páginas", "hubMeta": "PDF · en catalán", "hubOpen": "Abrir el PDF", "hubDownload": "Descargar", "hubRead": "Lee el texto aquí (en catalán)", "hubNav": "Bloques del trabajo", "igLabel": "INSTAGRAM / MAQUETA ACADÉMICA", "igText": "Seis publicaciones de muestra de la campaña de ocho semanas. Es una maqueta del plan de marketing; no es una cuenta real.", "igCta": "Consulta el plan de marketing", "igPosts": ["Seis jornadas, un solo camino. Presentamos la travesía.", "5.032 m: el día del paso Sunchulli.", "Pelechuco, donde empieza todo.", "¿Qué llevo en la mochila? La lista, en la web.", "Grupo pequeño: de 6 a 12 personas.", "Tres días en La Paz antes de caminar."], "igCredit": "Fotografías: Realnif, Raullike y Das Morton · Wikimedia Commons · CC BY-SA 4.0.", "treballNav": "Trabajo TD2", "condLabel": "CONDICIONES DEL VIAJE", "condTitle": "Las condiciones, claras desde el principio.", "conds": [["Grupo mínimo y máximo", "El viaje sale con un mínimo de 6 personas y un máximo de 12. Si no se llega al mínimo, te avisamos con tiempo y te proponemos otra fecha o te devolvemos todo lo que hayas pagado."], ["Qué incluye el precio", "Guía de montaña y guía local (con 9–12 personas se añade apoyo local), traslados en 4×4 del programa, mulas, todas las comidas y alojamientos del programa, tiendas y material colectivo, y seguro de viaje y actividad con trekking hasta 5.100 m, rescate y repatriación."], ["Días de reserva", "Los dos días de reserva están incluidos en el precio. Si hay que utilizarlos, no tienen coste adicional. Si una situación exigiera más días, te informaríamos del nuevo programa y del coste antes de continuar."], ["Requisitos para participar", "Experiencia en travesías de varios días, conversación previa con el guía, revisión con medicina del viajero y pasaporte vigente. Hay que disponer de 13 días, más los vuelos."], ["Cómo se reserva", "Cuando se abran las reservas: conversación previa, confirmación de plaza y contrato de viaje combinado con el calendario de pagos y las condiciones de cancelación. Andes Wild Trek actúa como organizador del viaje."], ["Cambios durante el viaje", "El guía puede modificar, acortar o detener una jornada por seguridad, meteorología o estado del grupo. La última jornada se puede terminar en Curva con vehículo. Estos cambios no tienen coste adicional."]], "condNote": "Las reservas todavía no están abiertas. Fechas, precio y condiciones definitivas se confirmarán tras el reconocimiento del recorrido.", "tw": {"title": "Trabajo TD2 · Andes Wild Trek · Apolobamba", "nav": ["El viaje", "El trabajo", "Planes B y C", "Bloques", "Herramientas", "Fuentes"], "eyebrow": "TRABAJO ACADÉMICO · TÉCNICO DEPORTIVO EN MEDIA MONTAÑA", "h1": "Andes Wild Trek<br>Apolobamba", "lead": "Proyecto de creación de una empresa de guiaje y de una travesía de seis jornadas entre Pelechuco y Charazani, Bolivia.", "meta": "Izan Pimentel Pérez · 16 de noviembre de 2026 · Documentos en catalán", "full": "Trabajo completo (PDF)", "word": "Versión editable (Word)", "back": "Ver la web del viaje", "keyLabel": "EL PROYECTO EN CUATRO PUNTOS", "keys": [["Empresa", "Agencia organizadora de viajes combinados con base en Cataluña y operador local en Bolivia."], ["Programa", "11 días y 2 de reserva: 3 de aclimatación, 1 de traslado, 6 jornadas a pie y 1 de regreso. Mejor época: de mediados de junio a finales de julio."], ["Presupuesto", "3.800 € por persona con un mínimo de 6; margen objetivo del 30%."], ["Siguiente paso", "Reconocimiento de campo, cotizaciones locales y permisos antes de comercializar."]], "present": "Presentación", "presentOff": "Salir del modo exposición", "toolsLabel": "HERRAMIENTAS DEL GUÍA Y ANEXOS", "toolsTitle": "Para aplicarlo<br>sobre el terreno.", "tools": [["Formularios operativos", "10 páginas · PDF", "Checklist diario, encuesta, autoevaluación, informe de mejora y expediente de apertura.", "dossiers/Apolobamba_Formularis_Operatius.pdf"], ["Atlas cartográfico", "10 láminas · PDF A3", "Las seis jornadas a pie y las cuatro etapas del plan C, con mapa topográfico, perfil, puntos de paso y vías de evacuación.", "dossiers/Apolobamba_Atles_Cartografic_A3.pdf"], ["Flyer con QR", "Imagen · JPG", "Pieza del plan de marketing con fotografía real; el QR abre la web del viaje.", "assets/flyer.jpg"], ["App del guía", "Móvil · sin cobertura", "Fichas técnicas de cada jornada con horas de control y decisiones, meteo, seguridad, listas, GPX y «¿Dónde estoy?».", "guia/"], ["Dossier completo del cliente", "18 páginas · PDF", "Documento que se envía al cliente cuando contacta: etapas punto a punto, mapas, clima y condiciones.", "dossiers/client/Dossier_Viaje_ES.pdf"]], "open": "Abrir", "sourcesLabel": "FUENTES", "sourcesTitle": "Contraste de la ruta", "mapLabel": "MAPA DEL TRABAJO", "mapTitle": "Cómo encajan las piezas.", "map": [["Empresa y mercado", [["Entorno laboral", "Modelo de agencia, público y DAFO", "empresa"], ["Normativa", "Titulación, contrato y seguros", "normativa"], ["Marketing", "Mensaje, campaña y flyer", "marketing"]]], ["Producto", [["Programa", "11 días + 2, seis jornadas y aclimatación", "empresa"], ["Presupuesto", "3.800 € con un mínimo de 6", "empresa"], ["Ficha del cliente", "Qué recibe quien se apunta", "client"]]], ["Operación", [["Metodología", "Conducción, dinámicas y evaluación", "metodologia"], ["Ficha del guía", "Horarios, puntos de decisión y mapas", "guia"], ["Formularios", "Checklist, encuesta y expediente", "eines"]]]], "mapBase": "Todo el trabajo descansa en dos límites: las competencias del TD2 en el paso Sunchulli y el reconocimiento de campo previo a la venta.", "planLabel": "TEMPORADA, PLANES B Y PLAN C", "planHeading": "Cuándo ir<br>y qué hacemos si no se puede pasar.", "planIntro": "Revisión del 17/11/2026 con fuentes de montañeros, operadores, la ABC y OpenStreetMap. Cada jornada tiene planes B y vías de evacuación, y el plan C es una ruta completa por el Akamani.", "planBTitle": "Planes B por jornada", "planCTitle": "Fichas técnicas del plan C", "roadsNote": "Consultado el", "colsC": ["Etapa", "Día", "Km", "Desnivel", "Máx.", "Duración", "Horario", "Noche"]}, "stageDossier": "Los puntos de paso, los mapas y los horarios detallados de cada jornada están en el dossier completo, que te enviamos cuando nos escribes.", "docRequest": "Pídelo", "seasonLabel": "CUÁNDO IR", "planTitle": "Si el camino no deja pasar", "planText": "Cada jornada tiene un plan B preparado y hay una ruta alternativa completa. Si hay que cambiar, el guía lo decide pensando en la seguridad del grupo.", "planItems": [["Paso Sunchulli (5.032 m)", "Hay hora límite: las 14:40. Si no llegamos a tiempo, si hay nieve dura o hielo o si el tiempo es malo, volvemos a Hilo Hilo y usamos un día de reserva."], ["Bajada de las Mil Curvas", "Con nieve, hielo o poca visibilidad no entramos. Hay una bajada alternativa más larga y menos empinada, o podemos dormir en la comunidad de Quellwa Cota."], ["Final de la travesía", "Si vamos justos de tiempo, terminamos en Curva y seguimos en vehículo hasta Charazani."], ["Plan C · por el Akamani", "Si el paso Sunchulli no es practicable o la zona minera no lo aconseja, hacemos la travesía por Cañisaya y el camino del Akamani hasta Charazani: cuatro jornadas, 35 km y un máximo de 4.661 m."], ["Pistas y evacuación", "Cerca de un tercio del camino va por pistas mineras. A cambio, en casi todo el recorrido un vehículo puede llegar si hay que evacuar a alguien."]]}};
